"""Production-style browser dashboard for the strategy API."""
from fastapi.responses import HTMLResponse

DASHBOARD_HTML = r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Race Engineer AI · Strategy Control Room</title><style>
:root{color-scheme:dark;--ink:#f4f7ff;--muted:#91a0bd;--line:#273552;--panel:#111b30;--panel2:#0d1628;--accent:#ff4d6d;--cyan:#5dd6e8;--green:#45db96;--amber:#f7c76a}*{box-sizing:border-box}body{margin:0;background:#08101f;color:var(--ink);font:14px Inter,system-ui,sans-serif}a{color:#9ed8ff}main{max-width:1280px;margin:auto;padding:28px 28px 54px}.topbar{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--line);padding-bottom:19px}.brand{font-size:12px;letter-spacing:.18em;font-weight:800}.brand span{color:var(--accent)}.session{color:var(--muted);font-size:12px;letter-spacing:.08em;text-transform:uppercase}.status{display:inline-flex;gap:8px;align-items:center;color:var(--green);border:1px solid #24634c;background:#10271f;padding:7px 11px;border-radius:999px;font-size:12px;font-weight:700}.dot{width:7px;height:7px;background:var(--green);border-radius:50%;box-shadow:0 0 12px var(--green)}.hero{display:flex;justify-content:space-between;gap:30px;align-items:end;padding:42px 0 30px}.eyebrow{color:var(--accent);letter-spacing:.15em;text-transform:uppercase;font-weight:800;font-size:11px}.hero h1{font-size:clamp(2.3rem,5vw,4.6rem);line-height:.98;letter-spacing:-.055em;margin:11px 0 14px;max-width:780px}.hero p{color:var(--muted);font-size:16px;max-width:640px;margin:0;line-height:1.5}.hero-meta{text-align:right;color:var(--muted);font-size:12px;line-height:1.7}.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:18px}.kpi,.card{background:linear-gradient(145deg,var(--panel),var(--panel2));border:1px solid var(--line);border-radius:12px}.kpi{padding:17px 18px}.kpi-label{color:var(--muted);font-size:11px;text-transform:uppercase;letter-spacing:.1em}.kpi-value{font-size:25px;font-weight:800;margin-top:8px}.kpi-note{color:var(--muted);font-size:12px;margin-top:4px}.layout{display:grid;grid-template-columns:360px minmax(0,1fr);gap:16px}.card{padding:22px}.card-head{display:flex;justify-content:space-between;align-items:start;margin-bottom:18px}.card h2{font-size:18px;margin:0;letter-spacing:-.02em}.label{display:flex;justify-content:space-between;color:var(--muted);font-size:12px;margin:15px 0 6px}.label b{color:var(--ink);font-weight:500}input,select{width:100%;background:#091325;border:1px solid #314264;border-radius:7px;color:var(--ink);padding:11px 12px;font:inherit;outline:none}input:focus,select:focus{border-color:var(--cyan);box-shadow:0 0 0 3px #5dd6e81c}.primary{width:100%;margin-top:19px;border:0;border-radius:7px;padding:12px;background:var(--accent);color:#fff;font-weight:800;cursor:pointer}.primary:hover{filter:brightness(1.1)}.decision{min-height:250px;display:flex;flex-direction:column}.decision-kicker{color:var(--muted);font-size:12px;text-transform:uppercase;letter-spacing:.12em}.decision-row{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:20px 0 14px}.call{font-size:36px;letter-spacing:-.05em;font-weight:900}.badge{padding:7px 10px;border-radius:5px;background:#263653;color:var(--cyan);font-size:11px;font-weight:800;letter-spacing:.1em}.delta{font-size:27px;font-weight:800}.delta small{font-size:12px;color:var(--muted);font-weight:500}.decision-copy{color:var(--muted);line-height:1.55;max-width:590px}.detail{margin-top:auto;padding-top:16px;border-top:1px solid var(--line);color:#b8c5dd;font-family:ui-monospace,monospace;font-size:12px;white-space:pre-wrap}.telemetry{margin-top:16px}.telemetry-tools{display:flex;gap:10px;align-items:center}.telemetry-tools select{width:120px}.chart-wrap{margin-top:18px;border:1px solid #22314f;border-radius:8px;background:#0a1426;padding:14px}.chart-wrap canvas{width:100%;height:225px;display:block}.chart-foot{display:flex;justify-content:space-between;color:var(--muted);font-size:12px;margin-top:10px}.evidence{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-top:16px}.metric-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.metric{background:#0b1527;border:1px solid #22314f;border-radius:8px;padding:14px}.metric strong{display:block;font-size:22px}.metric span{color:var(--muted);font-size:11px}.contracts{display:grid;grid-template-columns:1fr 1fr;gap:10px}.contract{padding:12px;border-left:2px solid var(--cyan);background:#0b1527;color:#b7c4da;font-size:12px;line-height:1.4}.footer{display:flex;justify-content:space-between;color:var(--muted);font-size:12px;margin-top:20px}.footer strong{color:var(--green)}@media(max-width:850px){main{padding:20px 16px}.hero{display:block;padding:30px 0 22px}.hero-meta{text-align:left;margin-top:16px}.kpis{grid-template-columns:repeat(2,1fr)}.layout,.evidence{grid-template-columns:1fr}.topbar .session{display:none}}@media(max-width:480px){.kpis,.metric-grid,.contracts{grid-template-columns:1fr 1fr}.kpi-value{font-size:20px}.call{font-size:29px}.telemetry-tools{display:block}.telemetry-tools select{width:100%;margin-top:8px}}
</style></head><body><main><header class="topbar"><div class="brand"><span>RACE ENGINEER</span> / PIT WALL INTELLIGENCE</div><div class="session">2024 · Monza · Race session</div><div class="status"><i class="dot"></i> API ONLINE</div></header><section class="hero"><div><div class="eyebrow">Strategy control room</div><h1>Make the next stop a decision, not a guess.</h1><p>Counterfactual pit timing built from filtered race telemetry, with the assumptions and evidence visible beside every recommendation.</p></div><div class="hero-meta">LIVE MODEL<br><strong id="hero-context">Loading session…</strong></div></section><section class="kpis"><div class="kpi"><div class="kpi-label">Session</div><div class="kpi-value">MONZA '24</div><div class="kpi-note">Race telemetry</div></div><div class="kpi"><div class="kpi-label">Processed laps</div><div class="kpi-value" id="kpi-laps">—</div><div class="kpi-note">Accurate samples</div></div><div class="kpi"><div class="kpi-label">Drivers</div><div class="kpi-value" id="kpi-drivers">—</div><div class="kpi-note">Available in session</div></div><div class="kpi"><div class="kpi-label">Season headline MAE</div><div class="kpi-value" id="headline-mae">—</div><div class="kpi-note" id="headline-note">Unseen-race evaluation</div></div></section><section class="layout"><form class="card" id="compare-form"><div class="card-head"><div><div class="eyebrow">Decision workspace</div><h2>Compare the next move</h2></div><span class="badge">COUNTERFACTUAL</span></div><label class="label">Laps remaining <b>race horizon</b></label><input name="laps_remaining" type="number" value="20" min="0"><label class="label">Current tyre age <b>laps on compound</b></label><input name="current_tyre_age" type="number" value="18" min="0"><label class="label">Current lap pace <b>seconds</b></label><input name="current_pace_seconds" type="number" value="90" step="0.1"><label class="label">Degradation per lap <b>seconds</b></label><input name="current_degradation_seconds_per_lap" type="number" value="0.08" step="0.01"><label class="label">Pit-lane loss <b>seconds</b></label><input name="pit_loss_seconds" type="number" value="22" step="0.5"><button class="primary">Run strategy comparison</button></form><article class="card decision"><div class="card-head"><div><div class="decision-kicker">Recommended action</div><h2>Race-time projection</h2></div><span class="badge" id="confidence">WAITING</span></div><div id="result"><p class="decision-copy">Load a driver context or run the comparison to see the projected race-time difference.</p></div></article></section><section class="card telemetry"><div class="card-head"><div><div class="eyebrow">Evidence layer</div><h2>Loaded telemetry</h2></div><div class="telemetry-tools"><select id="driver-select" aria-label="Driver"></select></div></div><div class="chart-wrap"><canvas id="pace-chart" width="900" height="225"></canvas><div class="chart-foot"><span id="telemetry-description">Filtered lap-time trace</span><span id="telemetry-status">Loading…</span></div></div><div class="footer"><span id="model-status">Model context loading…</span><span>Source: FastF1 · processed parquet</span></div></section><section class="evidence"><article class="card"><div class="card-head"><div><div class="eyebrow">Validation</div><h2>Backtest evidence</h2></div><span class="badge">TIME-AWARE</span></div><p class="decision-copy">Future laps are scored after the cutoff. The last-lap repeat baseline stays visible so model progress cannot be overstated.</p><div class="metric-grid"><div class="metric"><strong id="backtest-laps">—</strong><span>accurate laps</span></div><div class="metric"><strong id="backtest-drivers">—</strong><span>drivers</span></div><div class="metric"><strong id="backtest-marginal">—</strong><span>marginal calls</span></div></div></article><article class="card"><div class="card-head"><div><div class="eyebrow">Operating contract</div><h2>What the model assumes</h2></div></div><div class="contracts"><div class="contract">No future laps enter the fit. Context is anchored at the selected lap.</div><div class="contract">Pit windows respect the two-compound dry-race rule.</div><div class="contract">Track status, pit laps and deleted laps are filtered before fitting.</div><div class="contract" style="border-color:var(--amber)">Weather, radio and live timing are not connected yet.</div></div></article></section><footer class="footer"><span><strong>●</strong> <span id="dataset">Checking race data…</span></span><span><a href="/docs">Open API documentation</a></span></footer></main><script>
const form=document.querySelector('#compare-form'),result=document.querySelector('#result'),driverSelect=document.querySelector('#driver-select');function draw(values){const c=document.querySelector('#pace-chart'),x=c.getContext('2d'),w=c.width=c.clientWidth*2,h=c.height=450;x.clearRect(0,0,w,h);x.strokeStyle='#1d2b47';x.lineWidth=1;for(let i=1;i<5;i++){x.beginPath();x.moveTo(0,i*h/5);x.lineTo(w,i*h/5);x.stroke()}if(!values.length)return;const lo=Math.min(...values),hi=Math.max(...values);x.strokeStyle='#ff4d6d';x.lineWidth=5;x.beginPath();values.forEach((v,i)=>{const px=10+i*(w-20)/Math.max(values.length-1,1),py=h-18-(v-lo)/Math.max(hi-lo,.01)*(h-36);i?x.lineTo(px,py):x.moveTo(px,py)});x.stroke()}function loadTelemetry(driver){fetch(`/data/laps?driver=${driver}&limit=60`).then(r=>r.json()).then(l=>{const v=l.map(x=>x.lap_time_seconds).filter(x=>x>0);draw(v);document.querySelector('#telemetry-description').textContent=`${driver} · filtered lap-time trace`;document.querySelector('#telemetry-status').textContent=v.length?`${v.length} laps · ${Math.min(...v).toFixed(2)}–${Math.max(...v).toFixed(2)} s`:'No accurate telemetry'}).catch(()=>document.querySelector('#telemetry-status').textContent='Telemetry unavailable')}function loadContext(driver){fetch(`/data/context?driver=${driver}&lap=40`).then(r=>r.json()).then(c=>{if(!c.available)return;[['laps_remaining',c.laps_remaining],['current_tyre_age',c.tyre_age],['current_pace_seconds',c.current_pace_seconds]].forEach(([n,v])=>{const e=document.querySelector(`[name="${n}"]`);if(e)e.value=v});document.querySelector('#model-status').textContent=c.estimated_degradation_seconds_per_lap==null?'Degradation: baseline assumption':'Degradation: '+c.estimated_degradation_seconds_per_lap+' s/lap · '+c.degradation_source;document.querySelector('#hero-context').textContent=`${driver} · lap ${c.lap??'—'} · context loaded`;runComparison()})}fetch('/data/summary').then(r=>r.json()).then(d=>{document.querySelector('#dataset').textContent=d.available?`Monza 2024 · ${d.lap_count} laps · ${d.driver_count} drivers`:'Race data unavailable';document.querySelector('#kpi-laps').textContent=d.lap_count??'—';document.querySelector('#kpi-drivers').textContent=d.driver_count??'—';(d.drivers||[]).forEach(v=>{const o=document.createElement('option');o.value=v;o.textContent=v;driverSelect.appendChild(o)});if(d.drivers?.length){driverSelect.value=d.drivers.includes('VER')?'VER':d.drivers[0];loadTelemetry(driverSelect.value);loadContext(driverSelect.value)}});fetch('/evaluation/backtest').then(r=>r.json()).then(d=>{if(d.lap_count!==undefined){document.querySelector('#backtest-laps').textContent=d.lap_count??'—';document.querySelector('#backtest-drivers').textContent=d.drivers??'—';document.querySelector('#backtest-marginal').textContent=d.marginal_decisions??'—'}});fetch('/evaluation/season-headline').then(r=>r.json()).then(d=>{if(d.available){document.querySelector('#headline-mae').textContent=`${Number(d.model_mae_seconds).toFixed(3)}s`;document.querySelector('#headline-note').textContent=`Baseline ${Number(d.baseline_mae_seconds).toFixed(3)}s · ${d.races} unseen races`}}).catch(()=>{});driverSelect.addEventListener('change',()=>{loadTelemetry(driverSelect.value);loadContext(driverSelect.value)});async function runComparison(){const d=Object.fromEntries(new FormData(form));Object.keys(d).forEach(k=>d[k]=Number(d[k]));result.innerHTML='<p class="decision-copy">Calculating projected race time…</p>';const r=await fetch('/strategy/compare',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)}),o=await r.json();if(!r.ok){result.innerHTML=`<pre class="detail">${JSON.stringify(o,null,2)}</pre>`;return}const s=o.pit_now_advantage_seconds>=0?'advantage':'cost';result.innerHTML=`<div class="decision-row"><div class="call">${o.recommendation}</div><span class="badge">${o.decision_strength}</span></div><div class="delta">${Math.abs(o.pit_now_advantage_seconds).toFixed(1)}s <small>${s} vs alternative</small></div><p class="decision-copy">${o.recommendation==='PIT NOW'?'The projected pit-now total is lower over the remaining race distance.':'Staying out is currently faster after accounting for tyre degradation and pit-lane loss.'}</p><div class="detail">Stay out  ${o.stay_out_seconds.toFixed(1)}s\nPit now   ${o.pit_now_seconds.toFixed(1)}s</div>`;document.querySelector('#confidence').textContent=o.decision_strength}form.addEventListener('submit',e=>{e.preventDefault();runComparison()});</script></body></html>'''


def dashboard() -> HTMLResponse:
    return HTMLResponse(DASHBOARD_HTML)